package com.example.dacs3.activity

import android.os.Bundle
import android.text.Editable
import android.text.TextWatcher
import android.view.View
import android.widget.Toast
import androidx.activity.enableEdgeToEdge
import androidx.appcompat.app.AppCompatActivity
import androidx.recyclerview.widget.GridLayoutManager
import com.example.dacs3.adapter.FilmListAdapter
import com.example.dacs3.databinding.ActivityFilmsListBinding
import com.example.dacs3.model.Film
import com.google.firebase.database.DataSnapshot
import com.google.firebase.database.DatabaseError
import com.google.firebase.database.FirebaseDatabase
import com.google.firebase.database.ValueEventListener

class FilmsListActivity : AppCompatActivity() {

    private lateinit var binding: ActivityFilmsListBinding
    private val database = FirebaseDatabase.getInstance()
    private val allItems = ArrayList<Film>()
    private lateinit var adapter: FilmListAdapter

    override fun onCreate(savedInstanceState: Bundle?) {
        super.onCreate(savedInstanceState)
        binding = ActivityFilmsListBinding.inflate(layoutInflater)
        enableEdgeToEdge()
        setContentView(binding.root)

        val type = intent.getStringExtra("type") ?: "Items"
        setupRecyclerView()
        setupHeader(type)
        setupSearch()
        loadFilms(type)

        val type1 = intent.getStringExtra("type1") ?: "Upcomming"
        setupRecyclerView()
        setupHeader(type1)
        setupSearch()
        loadFilms(type1)
    }

    private fun setupHeader(type: String) {
        binding.titleFilmsList.text = if (type == "Upcoming") {
            "Upcoming Movies"
        } else {
            "Top Movies"
        }
        binding.backBtn.setOnClickListener { finish() }
    }

    private fun setupRecyclerView() {
        adapter = FilmListAdapter(ArrayList())
        binding.recyclerViewFilmsList.layoutManager = GridLayoutManager(this, 2)
        binding.recyclerViewFilmsList.adapter = adapter
    }

    private fun setupSearch() {
        binding.searchEditText.addTextChangedListener(object : TextWatcher {
            override fun beforeTextChanged(s: CharSequence?, start: Int, count: Int, after: Int) {
                // No-op
            }

            override fun onTextChanged(s: CharSequence?, start: Int, before: Int, count: Int) {
                filterFilms(s?.toString().orEmpty())
            }

            override fun afterTextChanged(s: Editable?) {
                // No-op
            }
        })
    }

    private fun filterFilms(query: String) {
        val keyword = query.trim().lowercase()
        if (keyword.isEmpty()) {
            adapter.updateItems(allItems)
            return
        }
        val filtered = allItems.filter { film ->
            film.Title?.lowercase()?.contains(keyword) == true
        }
        adapter.updateItems(filtered)
    }

    private fun loadFilms(type: String) {
        binding.progressBarFilmsList.visibility = View.VISIBLE
        allItems.clear()

        database.getReference(type)
            .addListenerForSingleValueEvent(object : ValueEventListener {
                override fun onDataChange(snapshot: DataSnapshot) {
                    if (snapshot.exists()) {
                        for (child in snapshot.children) {
                            val item = child.getValue(Film::class.java)
                            if (item != null) {
                                allItems.add(item)
                            }
                        }
                    }
                    adapter.updateItems(allItems)
                    binding.progressBarFilmsList.visibility = View.GONE
                }

                override fun onCancelled(error: DatabaseError) {
                    binding.progressBarFilmsList.visibility = View.GONE
                    Toast.makeText(this@FilmsListActivity, "Load failed: ${error.message}", Toast.LENGTH_SHORT).show()
                }
            })
    }
}

package com.example.dacs3.activity

import android.os.Bundle
import android.text.Editable
import android.text.TextWatcher
import android.view.View
import android.widget.Toast
import androidx.activity.enableEdgeToEdge
import androidx.appcompat.app.AppCompatActivity
import androidx.recyclerview.widget.GridLayoutManager
import com.example.dacs3.adapter.FilmListAdapter
import com.example.dacs3.databinding.ActivityFilmsListBinding
import com.example.dacs3.model.Film
import com.google.firebase.database.DataSnapshot
import com.google.firebase.database.DatabaseError
import com.google.firebase.database.FirebaseDatabase
import com.google.firebase.database.ValueEventListener

class FilmsListActivity : AppCompatActivity() {

    private lateinit var binding: ActivityFilmsListBinding
    private val database = FirebaseDatabase.getInstance()
    private val allItems = ArrayList<Film>()
    private lateinit var adapter: FilmListAdapter

    override fun onCreate(savedInstanceState: Bundle?) {
        super.onCreate(savedInstanceState)
        binding = ActivityFilmsListBinding.inflate(layoutInflater)
        enableEdgeToEdge()
        setContentView(binding.root)

        val type = intent.getStringExtra("type") ?: "Items"
        setupRecyclerView()
        setupHeader(type)
        setupSearch()
        loadFilms(type)
    }

    private fun setupHeader(type: String) {
        binding.titleFilmsList.text = when (type) {
            "Upcoming" -> "Upcoming Movies"
            "Favorites" -> "Favourite Movies"
            else -> "Top Movies"
        }
        binding.backBtn.setOnClickListener { finish() }
    }

    private fun setupRecyclerView() {
        adapter = FilmListAdapter(ArrayList())
        binding.recyclerViewFilmsList.layoutManager = GridLayoutManager(this, 2)
        binding.recyclerViewFilmsList.adapter = adapter
    }

    private fun setupSearch() {
        binding.searchEditText.addTextChangedListener(object : TextWatcher {
            override fun beforeTextChanged(s: CharSequence?, start: Int, count: Int, after: Int) {
                // No-op
            }

            override fun onTextChanged(s: CharSequence?, start: Int, before: Int, count: Int) {
                filterFilms(s?.toString().orEmpty())
            }

            override fun afterTextChanged(s: Editable?) {
                // No-op
            }
        })
    }

    private fun filterFilms(query: String) {
        val keyword = query.trim().lowercase()
        if (keyword.isEmpty()) {
            adapter.updateItems(allItems)
            return
        }
        val filtered = allItems.filter { film ->
            film.Title?.lowercase()?.contains(keyword) == true
        }
        adapter.updateItems(filtered)
    }

    private fun loadFilms(type: String) {
        binding.progressBarFilmsList.visibility = View.VISIBLE
        allItems.clear()

        if (type == "Favorites") {
            loadFavorites()
            return
        }

        database.getReference(type)
            .addListenerForSingleValueEvent(object : ValueEventListener {
                override fun onDataChange(snapshot: DataSnapshot) {
                    if (snapshot.exists()) {
                        for (child in snapshot.children) {
                            val item = child.getValue(Film::class.java)
                            if (item != null) {
                                allItems.add(item)
                            }
                        }
                    }
                    adapter.updateItems(allItems)
                    binding.progressBarFilmsList.visibility = View.GONE
                }

                override fun onCancelled(error: DatabaseError) {
                    binding.progressBarFilmsList.visibility = View.GONE
                    Toast.makeText(this@FilmsListActivity, "Load failed: ${error.message}", Toast.LENGTH_SHORT).show()
                }
            })
    }

    private fun loadFavorites() {
        val sharedPref = getSharedPreferences("UserPrefs", MODE_PRIVATE)
        val customUserId = sharedPref.getString("customUserId", null)

        if (customUserId.isNullOrEmpty()) {
            binding.progressBarFilmsList.visibility = View.GONE
            Toast.makeText(this, "Please login to view favourites", Toast.LENGTH_SHORT).show()
            return
        }

        database.getReference("Users").child(customUserId).child("favorites")
            .addListenerForSingleValueEvent(object : ValueEventListener {
                override fun onDataChange(snapshot: DataSnapshot) {
                    if (snapshot.exists()) {
                        for (child in snapshot.children) {
                            val item = child.getValue(Film::class.java)
                            if (item != null) {
                                allItems.add(item)
                            }
                        }
                    }
                    adapter.updateItems(allItems)
                    binding.progressBarFilmsList.visibility = View.GONE
                }

                override fun onCancelled(error: DatabaseError) {
                    binding.progressBarFilmsList.visibility = View.GONE
                    Toast.makeText(this@FilmsListActivity, "Load failed: ${error.message}", Toast.LENGTH_SHORT).show()
                }
            })
    }
}

package com.example.dacs3.activity

import android.content.Context
import android.content.Intent
import android.os.Bundle
import android.util.Log
import android.widget.Toast
import androidx.appcompat.app.AppCompatActivity
import com.example.dacs3.databinding.ActivityLoginBinding
import com.google.firebase.auth.FirebaseAuth
import com.google.firebase.database.FirebaseDatabase

class LoginActivity : AppCompatActivity() {
    private lateinit var binding: ActivityLoginBinding
    private lateinit var firebaseAuth: FirebaseAuth
    private lateinit var database: FirebaseDatabase

    override fun onCreate(savedInstanceState: Bundle?) {
        super.onCreate(savedInstanceState)
        binding = ActivityLoginBinding.inflate(layoutInflater)
        setContentView(binding.root)

        firebaseAuth = FirebaseAuth.getInstance()
        database = FirebaseDatabase.getInstance()

        // Check if user already logged in
        checkUserSession()

        binding.loginBtn.setOnClickListener {
            loginUser()
        }

        binding.registerTxt.setOnClickListener {
            startActivity(Intent(this, RegisterActivity::class.java))
            finish()
        }

        binding.forgotPasswordTxt.setOnClickListener {
            resetPassword()
        }
    }

    private fun loginUser() {
        val email = binding.emailEditText.text.toString().trim()
        val password = binding.passwordEditText.text.toString().trim()

        if (email.isEmpty() || password.isEmpty()) {
            Toast.makeText(this, "Please fill in all fields", Toast.LENGTH_SHORT).show()
            return
        }

        firebaseAuth.signInWithEmailAndPassword(email, password)
            .addOnCompleteListener { task ->
                if (task.isSuccessful) {
                    // Get username from database - search by email
                    val firebaseUid = firebaseAuth.currentUser?.uid
                    firebaseUid?.let {
                        database.getReference("Users").orderByChild("firebaseUid").equalTo(firebaseUid).get()
                            .addOnSuccessListener { snapshot ->
                                if (snapshot.exists()) {
                                    // User data exists
                                    for (userSnapshot in snapshot.children) {
                                        val customUserId = userSnapshot.child("customUserId").value?.toString() ?: "User"
                                        val username = userSnapshot.child("username").value?.toString() ?: "User"
                                        val savedPassword = userSnapshot.child("password").value?.toString() ?: ""

                                        // Save to SharedPreferences
                                        val sharedPref = getSharedPreferences("UserPrefs", Context.MODE_PRIVATE)
                                        sharedPref.edit().apply {
                                            putString("username", username)
                                            putString("email", email)
                                            putString("customUserId", customUserId)
                                            putString("firebaseUid", firebaseUid)
                                            putString("password", savedPassword)  // ⚠️ Lưu password
                                            if (binding.rememberCheckBox.isChecked) {
                                                putBoolean("rememberMe", true)
                                            }
                                            apply()
                                        }

                                        Toast.makeText(this, "Login successful", Toast.LENGTH_SHORT).show()
                                        startActivity(Intent(this, MainActivity::class.java))
                                        finish()
                                    }
                                } else {
                                    // User data not found - migrate from Auth
                                    migrateUserFromAuth(firebaseUid, email)
                                }
                            }
                    }
                } else {
                    Toast.makeText(this, "Login failed: ${task.exception?.message}", Toast.LENGTH_SHORT).show()
                }
            }
    }

    private fun migrateUserFromAuth(firebaseUid: String, email: String) {
        // Tạo entry cho user cũ từ Firebase Authentication
        database.getReference("Users").get()
            .addOnSuccessListener { snapshot ->
                val userCount = snapshot.childrenCount.toInt() + 1
                val customUserId = "MV$userCount"

                val userMap = mapOf(
                    "customUserId" to customUserId,
                    "firebaseUid" to firebaseUid,
                    "username" to email.substringBefore("@"), // Username = email prefix
                    "email" to email,
                    "password" to "unknown",  // ⚠️ Không biết password cũ
                    "permission" to "user",
                    "createdAt" to System.currentTimeMillis()
                )

                database.getReference("Users").child(customUserId).setValue(userMap)
                    .addOnCompleteListener { dbTask ->
                        if (dbTask.isSuccessful) {
                            // Save to SharedPreferences
                            val sharedPref = getSharedPreferences("UserPrefs", Context.MODE_PRIVATE)
                            sharedPref.edit().apply {
                                putString("username", email.substringBefore("@"))
                                putString("email", email)
                                putString("customUserId", customUserId)
                                putString("firebaseUid", firebaseUid)
                                putString("password", "unknown")
                                if (binding.rememberCheckBox.isChecked) {
                                    putBoolean("rememberMe", true)
                                }
                                apply()
                            }

                            Toast.makeText(this, "Account migrated! Login successful", Toast.LENGTH_SHORT).show()
                            startActivity(Intent(this, MainActivity::class.java))
                            finish()
                        } else {
                            Toast.makeText(this, "Error: ${dbTask.exception?.message}", Toast.LENGTH_SHORT).show()
                        }
                    }
            }
    }

    private fun resetPassword() {
        val email = binding.emailEditText.text.toString().trim()

        if (email.isEmpty()) {
            Toast.makeText(this, "Please enter your email", Toast.LENGTH_SHORT).show()
            return
        }

        firebaseAuth.sendPasswordResetEmail(email)
            .addOnCompleteListener { task ->
                if (task.isSuccessful) {
                    Toast.makeText(this, "Reset link sent to $email", Toast.LENGTH_SHORT).show()
                } else {
                    Toast.makeText(this, "Error: ${task.exception?.message}", Toast.LENGTH_SHORT).show()
                }
            }
    }

    private fun checkUserSession() {
        val sharedPref = getSharedPreferences("UserPrefs", Context.MODE_PRIVATE)
        val rememberMe = sharedPref.getBoolean("rememberMe", false)

        if (rememberMe && firebaseAuth.currentUser != null) {
            startActivity(Intent(this, MainActivity::class.java))
            finish()
        }
    }
}

package com.example.dacs3.activity

import android.content.Context
import android.content.Intent
import android.os.Bundle
import android.util.Log
import android.widget.Toast
import androidx.appcompat.app.AppCompatActivity
import com.example.dacs3.databinding.ActivityLoginBinding
import com.google.firebase.auth.FirebaseAuth
import com.google.firebase.database.FirebaseDatabase

class LoginActivity : AppCompatActivity() {
    private lateinit var binding: ActivityLoginBinding
    private lateinit var firebaseAuth: FirebaseAuth
    private lateinit var database: FirebaseDatabase

    override fun onCreate(savedInstanceState: Bundle?) {
        super.onCreate(savedInstanceState)
        binding = ActivityLoginBinding.inflate(layoutInflater)
        setContentView(binding.root)

        firebaseAuth = FirebaseAuth.getInstance()
        database = FirebaseDatabase.getInstance()

        // Check if user already logged in
        checkUserSession()

        binding.loginBtn.setOnClickListener {
            loginUser()
        }

        binding.registerTxt.setOnClickListener {
            startActivity(Intent(this, RegisterActivity::class.java))
            finish()
        }

        binding.forgotPasswordTxt.setOnClickListener {
            resetPassword()
        }
    }

    private fun loginUser() {
        val email = binding.emailEditText.text.toString().trim()
        val password = binding.passwordEditText.text.toString().trim()

        if (email.isEmpty() || password.isEmpty()) {
            Toast.makeText(this, "Please fill in all fields", Toast.LENGTH_SHORT).show()
            return
        }

        Log.d("LoginActivity", "Attempting login with email: $email")

        firebaseAuth.signInWithEmailAndPassword(email, password)
            .addOnCompleteListener { task ->
                if (task.isSuccessful) {
                    Log.d("LoginActivity", "Firebase Auth successful")
                    // Get username from database - search by email
                    val firebaseUid = firebaseAuth.currentUser?.uid
                    Log.d("LoginActivity", "Firebase UID: $firebaseUid")

                    firebaseUid?.let {
                        Log.d("LoginActivity", "Querying Users database...")
                        database.getReference("Users").orderByChild("firebaseUid").equalTo(firebaseUid).get()
                            .addOnSuccessListener { snapshot ->
                                Log.d("LoginActivity", "Query successful, exists: ${snapshot.exists()}, count: ${snapshot.childrenCount}")

                                if (snapshot.exists()) {
                                    // User data exists
                                    for (userSnapshot in snapshot.children) {
                                        val customUserId = userSnapshot.child("customUserId").value?.toString() ?: "User"
                                        val username = userSnapshot.child("username").value?.toString() ?: "User"
                                        val savedPassword = userSnapshot.child("password").value?.toString() ?: ""

                                        Log.d("LoginActivity", "Found user: $customUserId, $username")

                                        // Save to SharedPreferences
                                        val sharedPref = getSharedPreferences("UserPrefs", Context.MODE_PRIVATE)
                                        sharedPref.edit().apply {
                                            putString("username", username)
                                            putString("email", email)
                                            putString("customUserId", customUserId)
                                            putString("firebaseUid", firebaseUid)
                                            putString("password", savedPassword)
                                            if (binding.rememberCheckBox.isChecked) {
                                                putBoolean("rememberMe", true)
                                            }
                                            apply()
                                        }

                                        Log.d("LoginActivity", "SharedPreferences saved, navigating to MainActivity...")
                                        Toast.makeText(this, "Login successful", Toast.LENGTH_SHORT).show()
                                        startActivity(Intent(this, MainActivity::class.java))
                                        finish()
                                    }
                                } else {
                                    Log.d("LoginActivity", "User data not found in database, migrating...")
                                    // User data not found - migrate from Auth
                                    migrateUserFromAuth(firebaseUid, email)
                                }
                            }
                            .addOnFailureListener { e ->
                                Log.e("LoginActivity", "Query failed: ${e.message}")
                                Toast.makeText(this, "Error: ${e.message}", Toast.LENGTH_SHORT).show()
                            }
                    }
                } else {
                    Log.e("LoginActivity", "Login failed: ${task.exception?.message}")
                    Toast.makeText(this, "Login failed: ${task.exception?.message}", Toast.LENGTH_SHORT).show()
                }
            }
    }

    private fun migrateUserFromAuth(firebaseUid: String, email: String) {
        // Tạo entry cho user cũ từ Firebase Authentication
        database.getReference("Users").get()
            .addOnSuccessListener { snapshot ->
                val userCount = snapshot.childrenCount.toInt() + 1
                val customUserId = "MV$userCount"

                val userMap = mapOf(
                    "customUserId" to customUserId,
                    "firebaseUid" to firebaseUid,
                    "username" to email.substringBefore("@"), // Username = email prefix
                    "email" to email,
                    "password" to "unknown",  // ⚠️ Không biết password cũ
                    "permission" to "user",
                    "createdAt" to System.currentTimeMillis()
                )

                database.getReference("Users").child(customUserId).setValue(userMap)
                    .addOnCompleteListener { dbTask ->
                        if (dbTask.isSuccessful) {
                            // Save to SharedPreferences
                            val sharedPref = getSharedPreferences("UserPrefs", Context.MODE_PRIVATE)
                            sharedPref.edit().apply {
                                putString("username", email.substringBefore("@"))
                                putString("email", email)
                                putString("customUserId", customUserId)
                                putString("firebaseUid", firebaseUid)
                                putString("password", "unknown")
                                if (binding.rememberCheckBox.isChecked) {
                                    putBoolean("rememberMe", true)
                                }
                                apply()
                            }

                            Toast.makeText(this, "Account migrated! Login successful", Toast.LENGTH_SHORT).show()
                            startActivity(Intent(this, MainActivity::class.java))
                            finish()
                        } else {
                            Toast.makeText(this, "Error: ${dbTask.exception?.message}", Toast.LENGTH_SHORT).show()
                        }
                    }
            }
    }

    private fun resetPassword() {
        val email = binding.emailEditText.text.toString().trim()

        if (email.isEmpty()) {
            Toast.makeText(this, "Please enter your email", Toast.LENGTH_SHORT).show()
            return
        }

        firebaseAuth.sendPasswordResetEmail(email)
            .addOnCompleteListener { task ->
                if (task.isSuccessful) {
                    Toast.makeText(this, "Reset link sent to $email", Toast.LENGTH_SHORT).show()
                } else {
                    Toast.makeText(this, "Error: ${task.exception?.message}", Toast.LENGTH_SHORT).show()
                }
            }
    }

    private fun checkUserSession() {
        val sharedPref = getSharedPreferences("UserPrefs", Context.MODE_PRIVATE)
        val rememberMe = sharedPref.getBoolean("rememberMe", false)

        if (rememberMe && firebaseAuth.currentUser != null) {
            startActivity(Intent(this, MainActivity::class.java))
            finish()
        }
    }
}

package com.example.dacs3.activity

import android.content.Context
import android.content.Intent
import android.os.Bundle
import android.os.Handler
import android.os.Looper
import android.view.View
import android.widget.EditText
import android.widget.Toast
import androidx.activity.enableEdgeToEdge
import androidx.appcompat.app.AlertDialog
import androidx.appcompat.app.AppCompatActivity
import androidx.recyclerview.widget.LinearLayoutManager
import androidx.viewpager2.widget.CompositePageTransformer
import androidx.viewpager2.widget.MarginPageTransformer
import androidx.viewpager2.widget.ViewPager2
import com.example.dacs3.R
import com.example.dacs3.adapter.FilmListAdapter
import com.example.dacs3.adapter.SliderAdapter
import com.example.dacs3.databinding.ActivityMainBinding
import com.example.dacs3.model.Film
import com.example.dacs3.model.SliderItems
import com.google.firebase.auth.FirebaseAuth
import com.google.firebase.database.DataSnapshot
import com.google.firebase.database.DatabaseError
import com.google.firebase.database.DatabaseReference
import com.google.firebase.database.FirebaseDatabase
import com.google.firebase.database.ValueEventListener
import kotlin.math.abs

class MainActivity : AppCompatActivity() {

    private lateinit var binding: ActivityMainBinding
    private lateinit var database: FirebaseDatabase
    private lateinit var firebaseAuth: FirebaseAuth
    private val sliderHandle = Handler(Looper.getMainLooper())
    private val sliderRunnable = Runnable {
        binding.viewPager2.currentItem = binding.viewPager2.currentItem + 1
    }

    override fun onCreate(savedInstanceState: Bundle?) {
        super.onCreate(savedInstanceState)
        binding = ActivityMainBinding.inflate(layoutInflater)
        enableEdgeToEdge()
        setContentView(binding.root)

        database = FirebaseDatabase.getInstance()
        firebaseAuth = FirebaseAuth.getInstance()

        // Check user session
        checkUserSession()

        // Load user profile
        loadUserProfile()

        // Setup "See All" buttons
        binding.seeAllTopMovies.setOnClickListener {
            startActivity(Intent(this, FilmsListActivity::class.java).apply {
                putExtra("type", "Items")
            })
        }

        binding.seeAllUpcomingMovies.setOnClickListener {
            startActivity(Intent(this, FilmsListActivity::class.java).apply {
                putExtra("type", "Upcoming")
            })
        }

        // Setup Explore tab highlight
        binding.bottomNavigation.setItemSelected(R.id.explorer, true)
        binding.bottomNavigation.setOnItemSelectedListener { id ->
            when (id) {
                R.id.favourites -> {
                    startActivity(Intent(this, FilmsListActivity::class.java).apply {
                        putExtra("type", "Favorites")
                    })
                }
                R.id.explorer -> {
                    // Stay on Explore
                }
            }
        }

        // Setup logout button
        binding.logoutBtn.setOnClickListener {
            logoutUser()
        }

        // Setup UI
        initBanner()
        initTopMovies()
        initUpcoming()
    }

    private fun checkUserSession() {
        val sharedPref = getSharedPreferences("UserPrefs", Context.MODE_PRIVATE)
        val firebaseUid = sharedPref.getString("firebaseUid", null)

        if (firebaseUid == null) {
            // User not logged in, go to LoginActivity
            startActivity(Intent(this, LoginActivity::class.java))
            finish()
        }
    }

    private fun loadUserProfile() {
        val sharedPref = getSharedPreferences("UserPrefs", Context.MODE_PRIVATE)
        val username = sharedPref.getString("username", "User")

        // Handle "null" string case
        val displayName = if (username.isNullOrEmpty() || username == "null") "User" else username
        binding.textView3.text = "Hello $displayName"
    }

    private fun logoutUser() {
        // Sign out from Firebase
        firebaseAuth.signOut()

        // Clear SharedPreferences
        val sharedPref = getSharedPreferences("UserPrefs", Context.MODE_PRIVATE)
        sharedPref.edit().apply {
            clear()
            apply()
        }

        // Go to LoginActivity
        startActivity(Intent(this, LoginActivity::class.java))
        finish()
    }


        private fun initTopMovies() {
            val myRef : DatabaseReference = database.getReference("Items")
            binding.progressBarTopMovies.visibility = View.VISIBLE
            val items = ArrayList<Film>()

            myRef.addListenerForSingleValueEvent(object : ValueEventListener{
                override fun onDataChange(snapshot: DataSnapshot) {
                    if(snapshot.exists()){
                        for (i in snapshot.children){
                            val item = i.getValue(Film::class.java)
                            if(item != null){
                                items.add(item)
                            }
                        }
                        if(items.isNotEmpty()){
                            binding.recyclerViewTopMovies.layoutManager =
                                LinearLayoutManager(
                                    this@MainActivity,
                                    LinearLayoutManager.HORIZONTAL,
                                    false
                                )
                            binding.recyclerViewTopMovies.adapter = FilmListAdapter(items, false)
                        }
                    }
                    binding.progressBarTopMovies.visibility = View.GONE
                }

                override fun onCancelled(p0: DatabaseError) {

                }

            })
        }

        private fun initBanner() {
            val myRef = database.getReference("Banners")
            binding.progressBarSlider.visibility = View.VISIBLE

            myRef.addListenerForSingleValueEvent(object : ValueEventListener {
                override fun onDataChange(snapshot: DataSnapshot) {
                    val list = mutableListOf<SliderItems>()
                    for (data in snapshot.children) {
                        val item = data.getValue(SliderItems::class.java)
                        item?.let { list.add(it) }
                    }
                    banners(list)
                    binding.progressBarSlider.visibility = View.GONE
                }

                override fun onCancelled(error: DatabaseError) {
                }
            })
        }

        private fun banners(list: MutableList<SliderItems>) {
            binding.viewPager2.adapter = SliderAdapter(list, binding.viewPager2)
            binding.viewPager2.clipToPadding = false
            binding.viewPager2.clipChildren = false
            binding.viewPager2.offscreenPageLimit = 3

            val compositePageTransformer = CompositePageTransformer().apply {
                addTransformer(MarginPageTransformer(40))
                addTransformer { page, position ->
                    val r = 1 - abs(position)
                    page.scaleY = 0.85f + r * 0.15f
                }
            }
            binding.viewPager2.setPageTransformer(compositePageTransformer)
            binding.viewPager2.currentItem = 1
            binding.viewPager2.registerOnPageChangeCallback(object :
                ViewPager2.OnPageChangeCallback() {
                override fun onPageSelected(position: Int) {
                    super.onPageSelected(position)
                    sliderHandle.removeCallbacks(sliderRunnable)
                }
            })
        }

        private fun initUpcoming() {
            loadUpcoming("Upcoming", fallbackToLegacy = true)
        }

        private fun loadUpcoming(path: String, fallbackToLegacy: Boolean) {
            val myRef: DatabaseReference = database.getReference(path)
            binding.progressBarUpcoming.visibility = View.VISIBLE
            val items = ArrayList<Film>()

            myRef.addListenerForSingleValueEvent(object : ValueEventListener{
                override fun onDataChange(snapshot: DataSnapshot) {
                    if (snapshot.exists()) {
                        for (i in snapshot.children){
                            val item = i.getValue(Film::class.java)
                            if(item != null){
                                items.add(item)
                            }
                        }
                    }

                    if (items.isNotEmpty()) {
                        binding.recyclerViewUpcoming.layoutManager =
                            LinearLayoutManager(
                                this@MainActivity,
                                LinearLayoutManager.HORIZONTAL,
                                false
                            )
                        binding.recyclerViewUpcoming.adapter = FilmListAdapter(items, false)
                        binding.progressBarUpcoming.visibility = View.GONE
                        return
                    }

                    if (fallbackToLegacy && path == "Upcoming") {
                        loadUpcoming("Upcomming", fallbackToLegacy = false)
                    } else {
                        binding.progressBarUpcoming.visibility = View.GONE
                    }
                }

                override fun onCancelled(error: DatabaseError){
                    binding.progressBarUpcoming.visibility = View.GONE
                    Toast.makeText(this@MainActivity, "Upcoming load failed: ${error.message}", Toast.LENGTH_SHORT).show()
                }
            })
        }
    }

