package com.example.dacs3.activity

import android.content.Context
import android.content.Intent
import android.os.Bundle
import android.util.Log
import android.widget.Toast
import androidx.appcompat.app.AppCompatActivity
import com.example.dacs3.databinding.ActivityRegisterBinding
import com.google.firebase.auth.FirebaseAuth
import com.google.firebase.database.FirebaseDatabase

class RegisterActivity : AppCompatActivity() {
    private lateinit var binding: ActivityRegisterBinding
    private lateinit var firebaseAuth: FirebaseAuth
    private lateinit var database: FirebaseDatabase

    override fun onCreate(savedInstanceState: Bundle?) {
        super.onCreate(savedInstanceState)
        binding = ActivityRegisterBinding.inflate(layoutInflater)
        setContentView(binding.root)

        firebaseAuth = FirebaseAuth.getInstance()
        database = FirebaseDatabase.getInstance()

        binding.registerBtn.setOnClickListener {
            registerUser()
        }

        binding.loginTxt.setOnClickListener {
            startActivity(Intent(this, LoginActivity::class.java))
            finish()
        }
    }

    private fun registerUser() {
        val username = binding.usernameEditText.text.toString().trim()
        val email = binding.emailEditText.text.toString().trim()
        val password = binding.passwordEditText.text.toString().trim()
        val confirmPassword = binding.confirmPasswordEditText.text.toString().trim()

        // Validation
        if (username.isEmpty() || email.isEmpty() || password.isEmpty() || confirmPassword.isEmpty()) {
            Toast.makeText(this, "Please fill in all fields", Toast.LENGTH_SHORT).show()
            return
        }

        if (password != confirmPassword) {
            Toast.makeText(this, "Passwords do not match", Toast.LENGTH_SHORT).show()
            return
        }

        if (password.length < 6) {
            Toast.makeText(this, "Password must be at least 6 characters", Toast.LENGTH_SHORT).show()
            return
        }

        // Register with Firebase Auth
        Log.d("RegisterActivity", "Registering user: $email")
        firebaseAuth.createUserWithEmailAndPassword(email, password)
            .addOnCompleteListener { task ->
                if (task.isSuccessful) {
                    Log.d("RegisterActivity", "Auth successful, saving to database...")
                    val userId = firebaseAuth.currentUser?.uid
                    userId?.let {
                        // Save user info to Realtime Database
                        val userMap = mapOf(
                            "username" to username,
                            "email" to email,
                            "userId" to userId,
                            "permission" to "user",
                            "createdAt" to System.currentTimeMillis()
                        )

                        database.getReference("Users").child(it).setValue(userMap)
                            .addOnCompleteListener { dbTask ->
                                if (dbTask.isSuccessful) {
                                    Log.d("RegisterActivity", "User saved successfully: $it")
                                    // Save to SharedPreferences
                                    val sharedPref = getSharedPreferences("UserPrefs", Context.MODE_PRIVATE)
                                    sharedPref.edit().apply {
                                        putString("username", username)
                                        putString("email", email)
                                        putString("userId", userId)
                                        apply()
                                    }

                                    Toast.makeText(this, "Registration successful", Toast.LENGTH_SHORT).show()
                                    startActivity(Intent(this, MainActivity::class.java))
                                    finish()
                                } else {
                                    Log.e("RegisterActivity", "Error: ${dbTask.exception?.message}")
                                    Toast.makeText(this, "Error saving user data: ${dbTask.exception?.message}", Toast.LENGTH_SHORT).show()
                                }
                            }
                    }
                } else {
                    Log.e("RegisterActivity", "Auth failed: ${task.exception?.message}")
                    Toast.makeText(this, "Registration failed: ${task.exception?.message}", Toast.LENGTH_SHORT).show()
                }
            }
    }
}

package com.example.dacs3.activity

import android.content.Context
import android.content.Intent
import android.os.Bundle
import android.util.Log
import android.widget.Toast
import androidx.appcompat.app.AppCompatActivity
import com.example.dacs3.databinding.ActivityRegisterBinding
import com.google.firebase.auth.FirebaseAuth
import com.google.firebase.database.FirebaseDatabase

class RegisterActivity : AppCompatActivity() {
    private lateinit var binding: ActivityRegisterBinding
    private lateinit var firebaseAuth: FirebaseAuth
    private lateinit var database: FirebaseDatabase

    override fun onCreate(savedInstanceState: Bundle?) {
        super.onCreate(savedInstanceState)
        binding = ActivityRegisterBinding.inflate(layoutInflater)
        setContentView(binding.root)

        firebaseAuth = FirebaseAuth.getInstance()
        database = FirebaseDatabase.getInstance()

        binding.registerBtn.setOnClickListener {
            registerUser()
        }

        binding.loginTxt.setOnClickListener {
            startActivity(Intent(this, LoginActivity::class.java))
            finish()
        }
    }

    private fun registerUser() {
        val username = binding.usernameEditText.text.toString().trim()
        val email = binding.emailEditText.text.toString().trim()
        val password = binding.passwordEditText.text.toString().trim()
        val confirmPassword = binding.confirmPasswordEditText.text.toString().trim()

        // Validation
        if (username.isEmpty() || email.isEmpty() || password.isEmpty() || confirmPassword.isEmpty()) {
            Toast.makeText(this, "Please fill in all fields", Toast.LENGTH_SHORT).show()
            return
        }

        if (password != confirmPassword) {
            Toast.makeText(this, "Passwords do not match", Toast.LENGTH_SHORT).show()
            return
        }

        if (password.length < 6) {
            Toast.makeText(this, "Password must be at least 6 characters", Toast.LENGTH_SHORT).show()
            return
        }

        // Register with Firebase Auth
        Log.d("RegisterActivity", "Registering user: $email")
        firebaseAuth.createUserWithEmailAndPassword(email, password)
            .addOnCompleteListener { task ->
                if (task.isSuccessful) {
                    Log.d("RegisterActivity", "Auth successful, generating custom ID...")
                    val firebaseUid = firebaseAuth.currentUser?.uid

                    // Generate custom ID: MV1, MV2, MV3, ...
                    database.getReference("Users").get()
                        .addOnSuccessListener { snapshot ->
                            val userCount = snapshot.childrenCount.toInt() + 1
                            val customUserId = "MV$userCount"
                            Log.d("RegisterActivity", "Generated custom ID: $customUserId")

                            firebaseUid?.let {
                                // Save user info with custom ID
                                val userMap = mapOf(
                                    "customUserId" to customUserId,
                                    "firebaseUid" to firebaseUid,
                                    "username" to username,
                                    "email" to email,
                                    "permission" to "user",
                                    "createdAt" to System.currentTimeMillis()
                                )

                                database.getReference("Users").child(customUserId).setValue(userMap)
                                    .addOnCompleteListener { dbTask ->
                                        if (dbTask.isSuccessful) {
                                            Log.d("RegisterActivity", "User saved successfully: $customUserId")
                                            // Save to SharedPreferences
                                            val sharedPref = getSharedPreferences("UserPrefs", Context.MODE_PRIVATE)
                                            sharedPref.edit().apply {
                                                putString("username", username)
                                                putString("email", email)
                                                putString("customUserId", customUserId)
                                                putString("firebaseUid", firebaseUid)
                                                apply()
                                            }

                                            Toast.makeText(this, "Registration successful", Toast.LENGTH_SHORT).show()
                                            startActivity(Intent(this, MainActivity::class.java))
                                            finish()
                                        } else {
                                            Log.e("RegisterActivity", "Error: ${dbTask.exception?.message}")
                                            Toast.makeText(this, "Error saving user data: ${dbTask.exception?.message}", Toast.LENGTH_SHORT).show()
                                        }
                                    }
                            }
                        }
                } else {
                    Log.e("RegisterActivity", "Auth failed: ${task.exception?.message}")
                    Toast.makeText(this, "Registration failed: ${task.exception?.message}", Toast.LENGTH_SHORT).show()
                }
            }
    }
}

package com.example.dacs3.activity

import android.os.Bundle
import androidx.activity.enableEdgeToEdge
import androidx.appcompat.app.AppCompatActivity
import androidx.recyclerview.widget.GridLayoutManager
import androidx.recyclerview.widget.LinearLayoutManager
import com.example.dacs3.R
import com.example.dacs3.adapter.DateAdapter
import com.example.dacs3.adapter.SeatListAdapter
import com.example.dacs3.adapter.TimeAdapter
import com.example.dacs3.databinding.ActivitySeatListBinding
import com.example.dacs3.model.Film
import com.example.dacs3.model.Seat
import java.text.DecimalFormat
import java.time.LocalDate
import java.time.format.DateTimeFormatter

class SeatListActivity : AppCompatActivity() {
    private lateinit var binding: ActivitySeatListBinding
    private lateinit var film : Film
    private var price : Double = 0.0
    private var number : Int = 0

    override fun onCreate(savedInstanceState: Bundle?) {
        super.onCreate(savedInstanceState)
        enableEdgeToEdge()
        binding = ActivitySeatListBinding.inflate(layoutInflater)
        setContentView(binding.root)

        getIntentExtra()
        setVariable()
        initTimeDateList()
        initSeatsList()
    }

    private fun initSeatsList() {
        var gridLayoutManager = GridLayoutManager(this, 7)
        gridLayoutManager.spanSizeLookup = object  : GridLayoutManager.SpanSizeLookup() {
            override fun getSpanSize(position: Int): Int {
                return if (position % 7 == 3) 1 else 1
            }
        }

        binding.apply {
            seatRecyclerView.layoutManager = gridLayoutManager

            val seatList = mutableListOf<Seat>()
            val numberSeats = 81
            for (i in 0 until numberSeats) {
                val seatName = ""
                val seatStatus =
                    if (i == 2 || i == 20 || i == 33 || i == 41 || i == 50 || i == 72  || i == 73)
                        Seat.SeatStatus.UNAVAILABLE else Seat.SeatStatus.AVAILABLE
                seatList.add(Seat((seatStatus, seatName))
            }
            val seatAdapter = SeatListAdapter(seatList, this@SeatListActivity , object : SeatListAdapter.SelectedSeat {
                override fun Return(selectedName : String, num : Int) {
                    numberSelectedTxt.text = "$num Seats Selected"
                    val df = DecimalFormat("#,##")
                    price = df.format(num * film.price).toDouble()
                    number = num
                    priceTxt.text = "$$price"
                }
            })
            seatRecyclerView.adapter = seatAdapter
            seatRecyclerView.isNestedScrollingEnabled = false
        }
    }

    private fun initTimeDateList() {
        binding.apply {
            dateRecyclerview.layoutManager =
                LinearLayoutManager(
                    this@SeatListActivity ,
                    LinearLayoutManager.HORIZONTAL,
                    false)
            dateRecyclerview.adapter = DateAdapter(generateDates())

            TimeRecyclerview.layoutManager =
                LinearLayoutManager(
                    this@SeatListActivity ,
                    LinearLayoutManager.HORIZONTAL,
                    false)
            TimeRecyclerview.adapter = TimeAdapter(generateTimeSlots())
        }
    }

    private fun setVariable() {
        binding.backBtn.setOnClickListener { finish() }
    }

    private fun getIntentExtra() {
        film = intent.getSerializableExtra("film") as Film
    }

    private fun generateDates(): List<String> {
        val dates = mutableListOf<String>()
        val today = LocalDate.now()
        val formatter = DateTimeFormatter.ofPattern("EEE/dd/MMM")

        for (i in 0 until 7){
            dates.add(today.plusDays(i.toLong()).format(formatter))
        }
        return dates
    }

    private fun generateTimeSlots(): List<String> {
        val timeSlots = mutableListOf<String>()
        val formatter = DateTimeFormatter.ofPattern("HH:mm a")

        for (i in 0 until 24 step 2) {
            val time = LocalDate.now().atTime(i, 0).format(formatter)
            timeSlots.add(time)
        }
        return timeSlots
    }

}

